183: func newAPIHandler(store *Store) http.Handler {
184: 	mux := http.NewServeMux()
185: 	mux.HandleFunc("GET /api/todos", func(w http.ResponseWriter, _ *http.Request) {
186: 		todos, err := store.List()
187: 		if err != nil {
188: 			writeError(w, http.StatusInternalServerError, "could not list todos")
189: 			return
190: 		}
191: 		writeJSON(w, http.StatusOK, todos)
192: 	})
193: 	mux.HandleFunc("GET /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
194: 		id, ok := readID(w, r)
195: 		if !ok {
196: 			return
197: 		}
198: 		todo, err := store.Get(id)
199: 		if err != nil {
200: 			writeError(w, http.StatusNotFound, err.Error())
201: 			return
202: 		}
203: 		writeJSON(w, http.StatusOK, todo)
204: 	})
205: 	mux.HandleFunc("POST /api/todos", func(w http.ResponseWriter, r *http.Request) {
206: 		var input todoInput
207: 		if !readJSON(w, r, &input) {
208: 			return
209: 		}
210: 		todo, err := store.Create(input)
211: 		if err != nil {
212: 			writeError(w, http.StatusBadRequest, err.Error())
213: 			return
214: 		}
215: 		writeJSON(w, http.StatusCreated, todo)
216: 	})
217: 	mux.HandleFunc("PUT /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
218: 		id, ok := readID(w, r)
219: 		if !ok {
220: 			return
221: 		}
222: 		var input todoInput
223: 		if !readJSON(w, r, &input) {
224: 			return
225: 		}
226: 		todo, err := store.Update(id, input)
227: 		if errors.Is(err, errTodoNotFound) {
228: 			writeError(w, http.StatusNotFound, err.Error())
229: 			return
230: 		}
231: 		if err != nil {
232: 			writeError(w, http.StatusBadRequest, err.Error())
233: 			return
234: 		}
235: 		writeJSON(w, http.StatusOK, todo)
236: 	})
237: 	return mux
238: }
