66: func (s *Store) Close() error {
67: 	return s.db.Close()
68: }
69: 
70: func (s *Store) List() ([]Todo, error) {
71: 	rows, err := s.db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos ORDER BY id`)
72: 	if err != nil {
73: 		return nil, fmt.Errorf("list todos: %w", err)
74: 	}
75: 	defer rows.Close()
76: 
77: 	todos := make([]Todo, 0)
78: 	for rows.Next() {
79: 		todo, err := scanTodo(rows)
80: 		if err != nil {
81: 			return nil, err
82: 		}
83: 		todos = append(todos, todo)
84: 	}
85: 	if err := rows.Err(); err != nil {
86: 		return nil, fmt.Errorf("iterate todos: %w", err)
87: 	}
88: 	return todos, nil
89: }
90: 
91: func (s *Store) Get(id int64) (Todo, error) {
92: 	row := s.db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id)
93: 	todo, err := scanTodo(row)
94: 	if errors.Is(err, sql.ErrNoRows) {
95: 		return Todo{}, errTodoNotFound
96: 	}
97: 	return todo, err
98: }
99: 
100: func (s *Store) Create(input todoInput) (Todo, error) {
101: 	title := strings.TrimSpace(input.Title)
102: 	if title == "" {
103: 		return Todo{}, errTitleRequired
104: 	}
105: 
106: 	now := time.Now().UTC()
107: 	result, err := s.db.Exec(
108: 		`INSERT INTO todos (title, completed, created_at, updated_at) VALUES (?, ?, ?, ?)`,
109: 		title,
110: 		input.Completed,
111: 		now.Format(time.RFC3339Nano),
112: 		now.Format(time.RFC3339Nano),
113: 	)
114: 	if err != nil {
115: 		return Todo{}, fmt.Errorf("create todo: %w", err)
116: 	}
117: 	id, err := result.LastInsertId()
118: 	if err != nil {
119: 		return Todo{}, fmt.Errorf("read created todo id: %w", err)
120: 	}
121: 	return Todo{
122: 		ID:        id,
123: 		Title:     title,
124: 		Completed: input.Completed,
125: 		CreatedAt: now,
126: 		UpdatedAt: now,
127: 	}, nil
128: }
129: 
130: func (s *Store) Update(id int64, input todoInput) (Todo, error) {
131: 	title := strings.TrimSpace(input.Title)
132: 	if title == "" {
133: 		return Todo{}, errTitleRequired
134: 	}
135: 
136: 	updatedAt := time.Now().UTC()
137: 	result, err := s.db.Exec(
138: 		`UPDATE todos SET title = ?, completed = ?, updated_at = ? WHERE id = ?`,
139: 		title,
140: 		input.Completed,
141: 		updatedAt.Format(time.RFC3339Nano),
142: 		id,
143: 	)
144: 	if err != nil {
145: 		return Todo{}, fmt.Errorf("update todo: %w", err)
146: 	}
147: 	affected, err := result.RowsAffected()
148: 	if err != nil {
149: 		return Todo{}, fmt.Errorf("read updated row count: %w", err)
150: 	}
151: 	if affected == 0 {
152: 		return Todo{}, errTodoNotFound
153: 	}
154: 	return s.Get(id)
155: }
