		return fmt.Errorf("read deleted row count: %w", err)
	}
	if affected == 0 {
		return errTodoNotFound
	}
	return nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanTodo(row rowScanner) (Todo, error) {
	var todo Todo
	var completed int
	var createdAt string
	var updatedAt string
	if err := row.Scan(&todo.ID, &todo.Title, &completed, &createdAt, &updatedAt); err != nil {
		return Todo{}, err
	}

	var err error
	todo.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo created time: %w", err)
	}
	todo.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo updated time: %w", err)
	}
	todo.Completed = completed != 0
	return todo, nil
}

func newAPIHandler(store *Store) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/todos", func(w http.ResponseWriter, _ *http.Request) {
		todos, err := store.List()
		if err != nil {
			writeError(w, http.StatusInternalServerError, "could not list todos")
			return
		}
		writeJSON(w, http.StatusOK, todos)
	})
	mux.HandleFunc("GET /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, ok := readID(w, r)
		if !ok {
			return
		}
		todo, err := store.Get(id)
		if err != nil {
			writeError(w, http.StatusNotFound, err.Error())
			return
		}
		writeJSON(w, http.StatusOK, todo)
	})
	mux.HandleFunc("POST /api/todos", func(w http.ResponseWriter, r *http.Request) {
		var input todoInput
		if !readJSON(w, r, &input) {
			return
		}
		todo, err := store.Create(input)
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		writeJSON(w, http.StatusCreated, todo)
	})
	mux.HandleFunc("PUT /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, ok := readID(w, r)
		if !ok {
			return
		}
		var input todoInput
		if !readJSON(w, r, &input) {
			return
		}
		todo, err := store.Update(id, input)
		if errors.Is(err, errTodoNotFound) {
			writeError(w, http.StatusNotFound, err.Error())
			return
		}
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		writeJSON(w, http.StatusOK, todo)
	})
	mux.HandleFunc("DELETE /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, ok := readID(w, r)
		if !ok {
			return
		}
		if err := store.Delete(id); errors.Is(err, errTodoNotFound) {
			writeError(w, http.StatusNotFound, err.Error())
			return
		} else if err != nil {
			writeError(w, http.StatusInternalServerError, "could not delete todo")
			return
		}
		w.WriteHeader(http.StatusNoContent)
	})
	return mux
}

